  var h=0,i;for(i=0;i<d.length;i++)h=(h*31+d.charCodeAt(i))>>>0;
  var ks=DM_POOL.map(function(o){return o.k}),ids=[];
  /* 싱글·대전 중 하나는 꼭 들어가게: 첫 칸은 둘 중 하나 */
