  while(ids.length<3){h=(h*1103515245+12345)>>>0;var j=(h>>>8)%ks.length;ids.push(ks.splice(j,1)[0])}
  save.dm={d:d,ids:ids,v:{},got:{},all:false};persist();return save.dm}
