.crpanel .crnext{width:100%}
.crbtns{display:grid;grid-template-columns:1.35fr 1fr 1fr;gap:8px}
.crbtns .btn{min-width:0;min-height:50px;padding:6px 8px;font-size:clamp(14px,4.2vw,18px);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.crpanel .btn{max-width:100%}
#goal.camp{max-width:calc(100vw - 110px)}#goal.camp .goal-row{flex-wrap:wrap;row-gap:0}#goal.camp .goal-lab{max-width:100%}
.crbtns.solo{grid-template-columns:1fr 1fr}.crbtns.solo #crAgain{grid-column:1/-1;min-height:60px;font-size:22px}
/* 1.2.0(빌드 55) 결과창 다듬기: 모든 줄이 칸 안에서 줄바꿈되고 아이콘은 같은 크기 칸 가운데 */
.crpanel{display:grid;gap:12px}
.crpanel>*{min-width:0}
.crtitle{font-size:clamp(24px,7vw,30px);line-height:1.15}
.crprog{display:grid;gap:7px;padding:12px 14px;border-radius:16px;background:#EAF7FF;box-shadow:inset 0 0 0 2px rgba(44,120,196,.35);text-align:left}
.crp-top{display:flex;align-items:baseline;justify-content:space-between;gap:10px;min-width:0}
.crp-top b{font-size:15px;color:#0B2C4A;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.crp-top span{flex:0 0 auto;font-family:"Black Han Sans",Jua,sans-serif;font-size:17px;color:#2C78C4}
.crp-bar{height:12px;border-radius:99px;background:#C9DCEA;overflow:hidden;box-shadow:inset 0 2px 0 rgba(0,0,0,.08)}
